window.Chart85=(()=>{const $=id=>document.getElementById(id),num=v=>v===null||v===undefined||v===''?NaN:Number(v),fmt=(v,n=2)=>Number.isFinite(num(v))?num(v).toFixed(n):'UNKNOWN',dt=v=>{const s=String(v??'');return /^\d{8}$/.test(s)?s.slice(0,4)+'-'+s.slice(4,6)+'-'+s.slice(6):s};let stock,invalidDate=false,view={start:0,count:180},hover=null,drag=null;const rowValue=(r,k)=>num(r?.values?.[k]);
function updateControls(){const n=stock.chartRows.length;$('panRange').max=Math.max(0,n-view.count);$('panRange').value=view.start;$('prevWindow').disabled=view.start===0;$('nextWindow').disabled=view.start+view.count>=n;document.querySelectorAll('[data-window]').forEach(b=>b.classList.toggle('active',Math.min(Number(b.dataset.window),n)===view.count))}
function setWindow(count,end){const n=stock.chartRows.length;view.count=Math.max(10,Math.min(n,count));if(n<10)view.count=n;view.start=Math.max(0,Math.min(n-view.count,(end??(view.start+view.count))-view.count));hover=null;updateControls();drawChart()}
function drawChart(){if(!stock||invalidDate)return;const cv=$('chart'),box=cv.getBoundingClientRect(),w=Math.max(280,box.width),h=box.height,dpr=Math.min(window.devicePixelRatio||1,2);cv.width=w*dpr;cv.height=h*dpr;const c=cv.getContext('2d');c.setTransform(dpr,0,0,dpr,0,0);c.clearRect(0,0,w,h);c.fillStyle='#0d1727';c.fillRect(0,0,w,h);const L=w<500?47:60,R=12,T=12,B=28,pw=w-L-R,priceH=h*.57,volT=priceH+35,volH=h*.14,kT=volT+volH+30,kH=h-kT-B,step=pw/view.count,rows=stock.chartRows,rr=rows.slice(view.start,view.start+view.count),x=i=>L+(i+.5)*step;const values=rr.flatMap(r=>[num(r.low),num(r.high),...['白线','黄线','BBI'].map(k=>rowValue(r,k))]).filter(Number.isFinite);if(!values.length)return;let low=Math.min(...values),high=Math.max(...values);let span=high-low||Math.abs(high)*.05||1;low-=span*.08;high+=span*.12;const py=v=>T+(high-num(v))/(high-low)*priceH;const vmax=Math.max(1,...rr.map(r=>num(r.volume)).filter(Number.isFinite)),vy=v=>volT+volH-num(v)/vmax*volH;let ks=[0,100,...rr.flatMap(r=>['K','D','J'].map(k=>rowValue(r,k))).filter(Number.isFinite)],kmin=Math.min(...ks)-5,kmax=Math.max(...ks)+5,ky=v=>kT+(kmax-num(v))/(kmax-kmin)*kH;c.font='10px system-ui';c.textBaseline='middle';c.lineWidth=.7;function grid(top,height,min,max,ticks=3,format=v=>v.toFixed(2)){for(let i=0;i<=ticks;i++){const yy=top+i*height/ticks;c.strokeStyle='#223149';c.beginPath();c.moveTo(L,yy);c.lineTo(w-R,yy);c.stroke();c.fillStyle='#7f93ac';c.textAlign='right';c.fillText(format(max-(max-min)*i/ticks),L-7,yy)}}grid(T,priceH,low,high,4);grid(volT,volH,0,vmax,2,v=>Math.abs(v)>=1e6?(v/1e6).toFixed(1)+'M':v.toFixed(0));grid(kT,kH,kmin,kmax,2,v=>v.toFixed(0));c.save();c.beginPath();c.rect(L,T,pw,h-B-T+2);c.clip();const bw=Math.max(.6,Math.min(16,step*.65));rr.forEach((r,i)=>{const o=num(r.open),cl=num(r.close),hi=num(r.high),lo=num(r.low),xx=x(i),up=cl>=o;c.strokeStyle=up?'#f16678':'#43c7a0';c.fillStyle=c.strokeStyle;c.lineWidth=1;c.beginPath();c.moveTo(xx,py(hi));c.lineTo(xx,py(lo));c.stroke();const top=py(Math.max(o,cl)),bh=Math.max(1,Math.abs(py(o)-py(cl)));if(up)c.strokeRect(xx-bw/2,top,bw,bh);else c.fillRect(xx-bw/2,top,bw,bh);const prev=num(r.previousClose),rise=Number.isFinite(prev)?cl>prev:false,fall=Number.isFinite(prev)?cl<prev:false,hollow=(rise&&cl<o)||(fall&&cl>o);c.fillStyle=c.strokeStyle=rise?'#f16678':fall?'#43c7a0':'#7b8fa9';const vv=num(r.volume);if(Number.isFinite(vv)){if(hollow)c.strokeRect(xx-bw/2,vy(vv),bw,volT+volH-vy(vv));else c.fillRect(xx-bw/2,vy(vv),bw,volT+volH-vy(vv))}if($('showSignals').checked&&( ! $('signalFilter').value || $('signalFilter').value==='all'||r.values?.[$('signalFilter').value]===true)){if(r.values?.['一级买点']===true){c.fillStyle='#f3d17f';c.beginPath();c.moveTo(xx,py(lo)+7);c.lineTo(xx-4,py(lo)+14);c.lineTo(xx+4,py(lo)+14);c.closePath();c.fill()}else if(r.values?.['二级买点']===true){c.fillStyle='#91a8ff';c.beginPath();c.moveTo(xx,py(lo)+6);c.lineTo(xx-3,py(lo)+10);c.lineTo(xx,py(lo)+14);c.lineTo(xx+3,py(lo)+10);c.closePath();c.fill()}}if(String(r.date)===String(stock.anchor?.date)){c.strokeStyle='#64d4cb';c.setLineDash([3,4]);c.beginPath();c.moveTo(xx,T);c.lineTo(xx,volT+volH);c.stroke();c.setLineDash([])}});function line(k,col,map){c.strokeStyle=col;c.lineWidth=1.3;c.beginPath();let started=false;rr.forEach((r,i)=>{const v=rowValue(r,k);if(!Number.isFinite(v)){started=false;return}if(started)c.lineTo(x(i),map(v));else c.moveTo(x(i),map(v));started=true});c.stroke()}[['白线','#e8edf6'],['黄线','#edca70'],['BBI','#74aaff']].forEach(([k,col])=>line(k,col,py));[['K','#e8edf6'],['D','#edca70'],['J','#bf90df']].forEach(([k,col])=>line(k,col,ky));for(const [v,col]of[[stock.anchor?.body,'#b49ae5'],[stock.anchor?.low,'#60d4cb']]){if(Number.isFinite(num(v))&&num(v)>=low&&num(v)<=high){c.strokeStyle=col;c.lineWidth=.7;c.setLineDash([4,5]);c.beginPath();c.moveTo(L,py(v));c.lineTo(w-R,py(v));c.stroke();c.setLineDash([])}}if(hover!==null){const xx=x(hover);c.strokeStyle='#d1dbe680';c.setLineDash([2,3]);c.beginPath();c.moveTo(xx,T);c.lineTo(xx,kT+kH);c.stroke();c.setLineDash([])}c.restore();c.fillStyle='#91a4bb';c.textAlign='left';c.fillText('源成交量',L,volT-12);c.fillText('KDJ',L,kT-12);const ticks=Math.max(2,Math.floor(pw/110));for(let i=0;i<ticks;i++){const j=Math.round(i*(rr.length-1)/(ticks-1));c.textAlign=i===0?'left':i===ticks-1?'right':'center';c.fillText(dt(rr[j].date).slice(5),Math.max(L,Math.min(w-R,x(j))),h-10)}const r=rr[hover===null?rr.length-1:Math.min(rr.length-1,hover)];$('chartReadout').textContent=`${dt(r.date)}　开 ${fmt(r.open)}　高 ${fmt(r.high)}　低 ${fmt(r.low)}　收 ${fmt(r.close)}　量 ${fmt(r.volume,0)}　白 ${fmt(r.values?.['白线'])}　黄 ${fmt(r.values?.['黄线'])}　BBI ${fmt(r.values?.BBI)}`;cv._layout={L,pw,step};}

function bind(){document.querySelectorAll('[data-window]').forEach(b=>b.onclick=()=>setWindow(Number(b.dataset.window),stock.chartRows.length));$('dateSelect').onchange=e=>{const i=stock.chartRows.findIndex(r=>String(r.date)===e.target.value);if(i<0){invalidDate=true;hover=null;$('chart').getContext('2d').clearRect(0,0,$('chart').width,$('chart').height);$('chartReadout').textContent='';$('chart85Panel').hidden=true;$('chart85Unknown').hidden=false;$('chart85Unknown').textContent='所选日期不在该股已绑定图窗内，旧图已清空。请重新选择有效日期或股票。';return}invalidDate=false;$('chart85Panel').hidden=false;$('chart85Unknown').hidden=true;view.count=Math.min(60,stock.chartRows.length);view.start=Math.max(0,Math.min(stock.chartRows.length-view.count,i-Math.floor(view.count*.7)));hover=i-view.start;updateControls();drawChart()};$('panRange').oninput=e=>{view.start=Number(e.target.value);hover=null;updateControls();drawChart()};for(const [id,dir]of[['prevWindow',-1],['nextWindow',1]])$(id).onclick=()=>{view.start=Math.max(0,Math.min(stock.chartRows.length-view.count,view.start+dir*Math.max(1,Math.round(view.count/4))));hover=null;updateControls();drawChart()};$('showSignals').onchange=drawChart;$('signalFilter').onchange=drawChart;const cv=$('chart');cv.onpointerdown=e=>{drag={x:e.clientX,start:view.start};cv.setPointerCapture(e.pointerId)};cv.onpointerup=()=>{drag=null};cv.onpointercancel=()=>{drag=null};cv.onpointerleave=()=>{if(!drag){hover=null;drawChart()}};cv.onpointermove=e=>{if(!stock||!cv._layout)return;const{L,step}=cv._layout;if(drag){view.start=Math.max(0,Math.min(stock.chartRows.length-view.count,drag.start-Math.round((e.clientX-drag.x)/step)));updateControls()}const xx=e.clientX-cv.getBoundingClientRect().left;hover=Math.max(0,Math.min(view.count-1,Math.floor((xx-L)/step)));drawChart()};cv.addEventListener('wheel',e=>{e.preventDefault();const oldEnd=view.start+view.count;setWindow(Math.round(view.count*(e.deltaY>0?1.2:.8)),oldEnd)},{passive:false});window.addEventListener('resize',drawChart);}
function setStock(s){stock=s;invalidDate=false;view.count=Math.min(180,s.chartRows.length);view.start=Math.max(0,s.chartRows.length-view.count);hover=null;$('dateSelect').innerHTML=s.chartRows.map(r=>'<option value="'+r.date+'">'+dt(r.date)+'</option>').join('');$('dateSelect').value=s.chartRows.at(-1).date;updateControls();drawChart()}
function clear(){stock=null;invalidDate=false;$('chartReadout').textContent='';$('chart').getContext('2d').clearRect(0,0,$('chart').width,$('chart').height)}return {bind,setStock,drawChart,clear};})();